import { type FormEvent, type ReactNode, useEffect, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import {
  ArrowLeft, ArrowRight, Bell, CalendarDays, Check, ChevronRight, CircleAlert, CircleCheck,
  Clock3, Compass, Construction, Hammer, ImagePlus, Info, LoaderCircle, LockKeyhole,
  MapPin, MessageCircle, Navigation, Phone, Plus, Search, Settings2, ShieldCheck, Star,
  UserRound, UserRoundPlus, Wrench, X, Zap,
} from 'lucide-react';
import {
  getGetRequestsQueryKey, useCreateRequest, useGetLocations, useGetRequestById, useGetRequests,
  useGetUstaById, useGetUstas, useRegisterCustomer, useUpdateRequestStatus,
} from '@workspace/api-client-react';
import type { ServiceRequest, ServiceRequestInput, Usta, UstaLocation } from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const categories = [
  { id: 'elektrik', name: 'Elektrik', icon: Zap },
  { id: 'su', name: 'Su & tesisat', icon: Wrench },
  { id: 'insaat', name: 'İnşaat & tadilat', icon: Construction },
  { id: 'boya', name: 'Boya & dekorasyon', icon: Hammer },
  { id: 'temizlik', name: 'Ev temizliği', icon: Compass },
  { id: 'diger', name: 'Diğer işler', icon: Plus },
];
const serviceGroups = [
  { id: 'home', title: 'Ev & usta', subtitle: 'Elektrik, su, klima, boya, tadilat', icon: Wrench, tone: 'bg-[#f6d6c8] text-[#984d3a]', category: 'elektrik' },
  { id: 'cleaning', title: 'Temizlik', subtitle: 'Ev, ofis, taşınma sonrası', icon: Compass, tone: 'bg-[#d6e8df] text-[#30695f]', category: 'temizlik' },
  { id: 'moving', title: 'Nakliye & taşıma', subtitle: 'Eşya, parça, şehir içi', icon: Navigation, tone: 'bg-[#e8d8bd] text-[#7e5c2c]', category: 'diger' },
  { id: 'materials', title: 'Nalbur & malzeme', subtitle: 'İhtiyacını birlikte planlayalım', icon: Hammer, tone: 'bg-[#d9e6e8] text-[#31636a]', notice: 'Malzeme siparişi için hazırlık yapıyoruz. İstersen ihtiyacını talep olarak bırakabilirsin.' },
  { id: 'urgent', title: 'Acil ihtiyaç', subtitle: 'Hızlı usta, yol yardım, çilingir', icon: Zap, tone: 'bg-[#f5df9a] text-[#8d6819]', category: 'diger' },
  { id: 'life', title: 'Antalya yaşamı', subtitle: 'Duyurular, etkinlikler, rehber', icon: Bell, tone: 'bg-[#ded5e7] text-[#6c567c]', notice: 'Antalya yaşam rehberi çok yakında burada. Şimdilik çevrendeki hizmetleri keşfet.' },
];
const statusLabels: Record<string, string> = { Beklemede: 'Usta aranıyor', 'Devam Ediyor': 'İş devam ediyor', Tamamlandı: 'Tamamlandı', İptal: 'İptal edildi' };
const initials = (name = 'Usta') => name.split(' ').map((word) => word[0]).slice(0, 2).join('').toUpperCase();
const categoryName = (id?: string | null) => categories.find((category) => category.id === id)?.name ?? 'Genel hizmet';
const formatDate = (value?: string | null) => value ? new Intl.DateTimeFormat('tr-TR', { day: 'numeric', month: 'long' }).format(new Date(value)) : 'Tarih bekleniyor';
const isOpen = (status?: string) => !!status && !['Tamamlandı', 'İptal'].includes(status);

function Logo() {
  return <Link href="/" className="flex items-center gap-2" data-testid="link-home-logo"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-[0_3px_0_hsl(16_62%_44%)]"><Hammer size={18} strokeWidth={2.5} /></span><span className="display text-[1.23rem] font-bold tracking-[-.04em]">usta<span className="text-[hsl(var(--primary))]">cepte</span></span></Link>;
}

function Avatar({ usta, size = 'md' }: { usta?: Partial<Usta> | null; size?: 'sm' | 'md' | 'lg' }) {
  const sizeClass = size === 'lg' ? 'h-24 w-24 text-2xl' : size === 'sm' ? 'h-9 w-9 text-xs' : 'h-12 w-12 text-sm';
  return usta?.avatarUrl ? <img src={usta.avatarUrl} alt={usta.name ?? 'Usta'} className={`${sizeClass} rounded-xl object-cover`} data-testid={`img-avatar-${usta.id ?? 'profile'}`} /> : <div className={`${sizeClass} flex shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] font-bold text-[hsl(var(--secondary-foreground))]`} data-testid={`avatar-fallback-${usta?.id ?? 'profile'}`}>{initials(usta?.name)}</div>;
}

function Skeleton({ className = '' }: { className?: string }) { return <div className={`animate-pulse rounded-lg bg-[hsl(var(--muted))] ${className}`} aria-label="Yükleniyor" />; }
function QueryError({ onRetry }: { onRetry: () => void }) { return <div className="card flex flex-col items-center justify-center gap-3 p-8 text-center"><CircleAlert className="text-[hsl(var(--destructive))]" /><p className="font-semibold">Bir şeyler ters gitti.</p><p className="muted text-sm">Bağlantınızı kontrol edip tekrar deneyin.</p><button onClick={onRetry} className="btn btn-secondary" data-testid="button-retry">Tekrar dene</button></div>; }

function BottomNav() {
  const [location] = useLocation();
  const items = [{ href: '/', label: 'Keşfet', icon: Compass }, { href: '/islerim', label: 'Taleplerim', icon: Construction }, { href: '/bildirimler', label: 'Bildirimler', icon: Bell }, { href: '/hesabim', label: 'Hesabım', icon: UserRound }];
  return <nav className="fixed bottom-3 left-3 right-3 z-10 flex items-center rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card)/.97)] p-1.5 shadow-[var(--shadow-md)] backdrop-blur-md md:hidden" data-testid="nav-destinations"><div className="grid flex-1 grid-cols-4">{items.map(({ href, label, icon: Icon }) => { const active = location === href || (href === '/islerim' && location.startsWith('/islerim/')); return <Link href={href} key={href} className={`flex flex-col items-center gap-1 rounded-xl px-1 py-2 text-[10px] font-bold ${active ? 'bg-[hsl(var(--muted))] text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))]'}`} data-testid={`link-nav-${label.replaceAll(' ', '-').toLowerCase()}`}><Icon size={17} /><span>{label}</span></Link>; })}</div><Link href="/talep" className="ml-1 flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-[0_3px_0_hsl(16_62%_44%)]" data-testid="link-nav-new-request"><Plus size={21} /></Link></nav>;
}

function Shell({ children, userName }: { children: ReactNode; userName: string | null }) {
  return <div className="min-h-[100dvh]"><header className="sticky top-0 z-10 border-b border-[hsl(var(--border)/.72)] bg-[hsl(var(--background)/.93)] backdrop-blur-md"><div className="mx-auto flex h-[72px] max-w-7xl items-center justify-between px-4 lg:px-8"><Logo /><nav className="hidden items-center gap-6 md:flex"><Link href="/" className="text-sm font-semibold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">Keşfet</Link><Link href="/islerim" className="text-sm font-semibold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">Taleplerim</Link><Link href="/bildirimler" className="text-sm font-semibold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">Bildirimler</Link><Link href="/hesabim" className="text-sm font-semibold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">Hesabım</Link><span className="flex items-center gap-1.5 text-xs font-bold text-[hsl(var(--secondary-foreground))]"><MapPin size={14} /> Antalya</span><Link href="/talep" className="btn btn-primary min-h-10 px-4 text-sm" data-testid="link-header-new-request"><Plus size={16} /> Talep oluştur</Link></nav><Link href="/hesabim" className="flex items-center gap-2 rounded-xl p-1.5 hover:bg-[hsl(var(--muted))] md:hidden" data-testid="link-header-account"><Avatar usta={userName ? { name: userName } : undefined} size="sm" /></Link></div></header><main className="mx-auto max-w-7xl px-4 py-8 pb-28 lg:px-8 md:pb-10">{children}</main><BottomNav /></div>;
}

function Home() {
  const [, setLocation] = useLocation();
  const ustas = useGetUstas();
  const locations = useGetLocations();
  const requests = useGetRequests();
  const online = (ustas.data ?? []).filter((usta) => usta.isOnline);
  const active = (requests.data ?? []).find((request) => isOpen(request.status));
  const [notice, setNotice] = useState<string | null>(null);
  const scrollToNearby = () => document.getElementById('nearby')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  const launchGroup = (group: typeof serviceGroups[number]) => { if (group.notice) setNotice(group.notice); else setLocation(`/talep?category=${group.category}`); };
  return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><div className="page-enter mx-auto max-w-6xl">
    <section className="mb-10 grid gap-8 pt-3 md:grid-cols-[1.15fr_.85fr] md:items-center"><div className="reveal-1"><p className="mb-4 text-sm font-bold text-[hsl(var(--primary))]">Antalya’nın günlük işleri için</p><h1 className="display max-w-2xl text-5xl font-bold leading-[.99] tracking-[-.07em] md:text-[4.35rem]">İhtiyacınız neyse,<br /><span className="text-[hsl(var(--primary))]">Usta Cepte.</span></h1><p className="muted mt-5 max-w-lg text-base leading-7">Evden taşınmaya, acil yardımdan Antalya yaşamına kadar şehirdeki ihtiyaçlarınız için tek bir yer.</p><Link href="/talep" className="btn btn-primary mt-7 min-h-14 w-full px-6 text-base sm:w-auto" data-testid="button-start-request">Hemen talep oluştur <ArrowRight size={18} /></Link><button onClick={scrollToNearby} className="ml-0 mt-4 flex items-center gap-2 text-sm font-bold text-[hsl(var(--secondary-foreground))] hover:text-[hsl(var(--primary))]" data-testid="button-see-nearby"><MapPin size={16} /> Yakınımdaki ustaları keşfet</button></div><ServiceIllustration /></section>
    {active && <Link href={`/islerim/${active.id}`} className="card mb-10 flex items-center gap-4 border-[hsl(var(--primary)/.35)] bg-[hsl(var(--accent)/.25)] p-4" data-testid={`card-active-request-${active.id}`}><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><Navigation size={19} /></span><span className="min-w-0 flex-1"><span className="label mb-1">Devam eden talebin</span><strong className="block truncate">{active.title || active.categoryName}</strong><small className="muted">{statusLabels[active.status] ?? active.status} · {active.semt}</small></span><ChevronRight className="muted" /></Link>}
    <section className="service-launcher mb-14"><div className="mb-5 flex items-end justify-between"><div><p className="label">Hizmetler</p><h2 className="display text-3xl font-bold">Neye ihtiyacın var?</h2></div><span className="muted hidden text-sm sm:block">Bir alan seç, hemen başlayalım</span></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{serviceGroups.map((group) => <button type="button" key={group.id} onClick={() => launchGroup(group)} className={`service-area card p-5 text-left ${group.tone}`} data-testid={`service-group-${group.id}`}><span className="service-glyph bg-[hsl(var(--card)/.75)]"><group.icon size={25} /></span><div className="relative z-[1] pr-14"><h3 className="display text-xl font-bold">{group.title}</h3><p className="mt-2 max-w-[15rem] text-sm leading-5 opacity-80">{group.subtitle}</p><span className="mt-5 inline-flex items-center gap-1 text-xs font-bold">Keşfet <ArrowRight size={14} /></span></div></button>)}</div>{notice && <div className="notice-card mt-4 flex items-start gap-3 rounded-xl p-4 text-sm"><Info size={17} className="mt-0.5 shrink-0 text-[hsl(var(--primary))]" /><div className="flex-1"><p>{notice}</p><button onClick={() => setLocation('/talep?category=diger')} className="mt-2 font-bold text-[hsl(var(--primary))]" data-testid="button-notice-request">İhtiyacını talep olarak bırak <ArrowRight size={14} className="ml-1 inline" /></button></div><button onClick={() => setNotice(null)} className="muted" aria-label="Bilgiyi kapat">×</button></div>}</section>
    <HowItWorks />
    <EmergencySection onRequest={() => setLocation('/talep?category=diger')} />
    <NearbySection ustas={ustas.data ?? []} online={online} locations={locations.data ?? []} isLoading={ustas.isLoading || locations.isLoading} isError={ustas.isError || locations.isError} retry={() => { void ustas.refetch(); void locations.refetch(); }} />
    <LifeSection />
  </div></Shell>;
}

function ServiceIllustration() {
  return <div className="hero-art reveal-2 mx-auto w-full max-w-xl rounded-[1.6rem]"><span className="hero-tag">Usta Cepte / Antalya</span><div className="hero-arch" /><div className="hero-orbit"><Hammer size={28} strokeWidth={1.5} /></div><div className="hero-caption"><p className="display text-3xl leading-none">İyi iş,<br />iyi his.</p><p className="mt-3 text-xs text-[hsl(var(--card)/.7)]">Evinize özenle seçilmiş<br />bir usta gelsin.</p></div></div>;
}

function HowItWorks() {
  const steps = [{ number: '1', title: 'İhtiyacını anlat', text: 'İşini ve adresini birkaç adımda paylaş.' }, { number: '2', title: 'Ustanı bulalım', text: 'Yakınındaki uygun ustalarla eşleştirelim.' }, { number: '3', title: 'İşini takip et', text: 'Talebinin her aşamasını tek yerden gör.' }];
  const icons = [Search, ShieldCheck, Navigation];
  return <section className="border-y border-[hsl(var(--border))] py-10"><div className="mb-7 flex items-end justify-between"><div><p className="label">Nasıl çalışır?</p><h2 className="display text-3xl font-bold">Sizin için kolaylaştırdık.</h2></div><span className="muted hidden text-sm md:block">Kısa, şeffaf, güvenilir</span></div><div className="grid gap-5 md:grid-cols-3">{steps.map((step, index) => { const Icon = icons[index]; return <div className="editorial-card overflow-hidden rounded-lg bg-[hsl(var(--card))] p-4" key={step.number}><div className="step-mark mb-4"><Icon size={30} strokeWidth={1.5} /></div><div className="flex gap-3"><span className="text-sm font-bold text-[hsl(var(--primary))]">0{step.number}</span><div><h3 className="font-bold">{step.title}</h3><p className="muted mt-1 text-sm leading-6">{step.text}</p></div></div></div>; })}</div></section>;
}

function EmergencySection({ onRequest }: { onRequest: () => void }) {
  return <section className="my-14 grid gap-5 md:grid-cols-[.8fr_1.2fr] md:items-stretch"><div className="city-ribbon rounded-2xl p-6 md:p-8"><div className="relative z-[1]"><p className="mb-4 text-sm font-bold text-[hsl(var(--accent))]">Acil ihtiyaç</p><h2 className="display text-3xl font-bold leading-tight">Beklemeye<br />gerek yok.</h2><p className="mt-4 max-w-xs text-sm leading-6 text-[hsl(var(--card)/.72)]">Hızlı bir usta, çilingir ya da yol yardımı gerekiyorsa talebini bırak.</p><button onClick={onRequest} className="btn mt-7 border border-[hsl(var(--card)/.3)] bg-[hsl(var(--card)/.12)] text-[hsl(var(--card))] hover:bg-[hsl(var(--card)/.2)]" data-testid="button-emergency-request">Acil talep oluştur <ArrowRight size={16} /></button></div></div><div className="notice-card rounded-2xl p-6 md:p-8"><div className="flex h-full flex-col justify-between"><div><p className="label">Bugün çevrende</p><h2 className="display mt-1 text-3xl font-bold">Yakında burada.</h2><p className="muted mt-3 max-w-md leading-6">Semtindeki fırsatlar, yerel duyurular ve ihtiyaç anında işine yarayacak kısa yolları bu alanda toplamaya hazırlanıyoruz.</p></div><div className="mt-8 flex items-center gap-3 text-sm font-semibold text-[hsl(var(--secondary-foreground))]"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-[hsl(var(--secondary))]"><Bell size={17} /></span> İçerik geldikçe burada göreceksin.</div></div></div></section>;
}

function LifeSection() {
  return <section className="border-t border-[hsl(var(--border))] py-12"><div className="mb-6 flex items-end justify-between"><div><p className="label">Antalya yaşamı</p><h2 className="display text-3xl font-bold">Şehri birlikte keşfedelim.</h2></div><span className="muted hidden text-sm sm:block">Duyurular · etkinlikler · rehber</span></div><div className="grid gap-4 md:grid-cols-3"><LifeCard title="Yerel duyurular" text="Mahallenden haberler burada toplanacak." icon={<MessageCircle size={21} />} /><LifeCard title="Bu hafta Antalya" text="Etkinlik ve şehir rehberi yakında." icon={<CalendarDays size={21} />} /><LifeCard title="Küçük rehber" text="İşini kolaylaştıracak yerel öneriler." icon={<MapPin size={21} />} /></div></section>;
}

function LifeCard({ title, text, icon }: { title: string; text: string; icon: ReactNode }) {
  return <div className="notice-card rounded-xl p-5"><span className="mb-5 flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]">{icon}</span><h3 className="font-bold">{title}</h3><p className="muted mt-2 text-sm leading-6">{text}</p><span className="mt-4 inline-block text-xs font-bold text-[hsl(var(--primary))]">Çok yakında</span></div>;
}

function NearbySection({ ustas, online, locations, isLoading, isError, retry }: { ustas: Usta[]; online: Usta[]; locations: UstaLocation[]; isLoading: boolean; isError: boolean; retry: () => void }) {
  const [, setLocation] = useLocation();
  return <section id="nearby" className="scroll-mt-24 py-12"><div className="mb-6 flex items-end justify-between"><div><p className="label">Yakınında</p><h2 className="display text-3xl font-bold">Ustalar burada.</h2></div><span className="muted hidden text-sm sm:block">{online.length} usta şu an müsait</span></div>{isLoading ? <div className="grid gap-3 md:grid-cols-[1.15fr_.85fr]"><Skeleton className="h-48" /><Skeleton className="h-48" /></div> : isError ? <QueryError onRetry={retry} /> : <div className="grid gap-3 md:grid-cols-[1.15fr_.85fr]"><div className="editorial-card card divide-y divide-[hsl(var(--border))]">{online.slice(0, 3).length ? online.slice(0, 3).map((usta) => <button type="button" key={usta.id} onClick={() => setLocation(`/usta/${usta.id}`)} className="flex w-full items-center gap-4 p-4 text-left hover:bg-[hsl(var(--muted)/.55)]" data-testid={`nearby-usta-${usta.id}`}><Avatar usta={usta} size="md" /><span className="min-w-0 flex-1"><strong className="block truncate">{usta.name}</strong><small className="muted mt-1 block truncate">{usta.specialty} · {usta.district || 'Antalya'}</small><span className="mt-2 block text-xs text-[hsl(var(--secondary-foreground))]">Bugün hizmet verebilir</span></span><span className="text-right"><span className="flex items-center gap-1 text-xs font-bold"><Star size={12} fill="currentColor" className="text-[#b27d16]" /> {usta.rating.toFixed(1)}</span><small className="mt-1 block text-[10px] font-bold text-[hsl(var(--primary))]">Müsait</small></span><ChevronRight className="muted" size={17} /></button>) : <div className="p-8 text-center"><p className="font-bold">Şu an müsait usta yok.</p><p className="muted mt-1 text-sm">Talebini bırak, ilk uygun ustayı bulalım.</p></div>}</div><div className="card overflow-hidden">{locations.length ? <div className="simple-map relative h-48"><div className="absolute left-4 top-4 z-[1] rounded-lg bg-[hsl(var(--card)/.9)] px-3 py-2 text-xs font-bold shadow-[var(--shadow-sm)]"><MapPin className="mr-1 inline text-[hsl(var(--primary))]" size={14} /> Antalya</div>{locations.slice(0, 3).map((location, index) => <span key={location.ustaId} className={`absolute z-[1] flex h-8 w-8 items-center justify-center rounded-full border-2 border-[hsl(var(--card))] text-[hsl(var(--primary-foreground))] shadow-[var(--shadow-sm)] ${index === 0 ? 'left-[58%] top-[48%]' : index === 1 ? 'left-[30%] top-[34%]' : 'left-[72%] top-[68%]'}`} style={{ backgroundColor: index === 1 ? 'hsl(var(--secondary-foreground))' : 'hsl(var(--primary))' }}><Hammer size={13} /></span>)}</div> : <div className="flex h-48 items-center justify-center bg-[hsl(var(--muted)/.55)] p-6 text-center"><div><MapPin className="mx-auto mb-2 muted" /><p className="font-bold">Harita yakında burada.</p><p className="muted mt-1 text-sm">Müsait usta olduğunda yakınını görebilirsin.</p></div></div>}<div className="flex items-center justify-between border-t border-[hsl(var(--border))] px-4 py-3"><span className="muted text-xs">Yakındaki ekip</span><button onClick={() => setLocation('/talep')} className="text-sm font-bold text-[hsl(var(--primary))]" data-testid="button-nearby-request">Talep oluştur</button></div></div></div>}</section>;
}

function RequestList() {
  const requests = useGetRequests(); const [tab, setTab] = useState('active'); const list = requests.data ?? []; const filtered = list.filter((request) => tab === 'active' ? isOpen(request.status) : tab === 'past' ? request.status === 'Tamamlandı' : request.status === 'İptal');
  return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><div className="page-enter mx-auto max-w-4xl"><PageHeading eyebrow="İşlerim" title="Taleplerini takip et" action={<Link href="/talep" className="btn btn-primary" data-testid="link-new-request"><Plus size={17} /> Yeni talep</Link>} /><div className="mb-6 flex gap-1 border-b border-[hsl(var(--border))]"><TabButton active={tab === 'active'} onClick={() => setTab('active')} label="Aktif" count={list.filter((r) => isOpen(r.status)).length} testId="tab-active" /><TabButton active={tab === 'past'} onClick={() => setTab('past')} label="Geçmiş" count={list.filter((r) => r.status === 'Tamamlandı').length} testId="tab-past" /><TabButton active={tab === 'cancelled'} onClick={() => setTab('cancelled')} label="İptal" count={list.filter((r) => r.status === 'İptal').length} testId="tab-cancelled" /></div>{requests.isLoading ? <div className="space-y-3">{[1, 2, 3].map((item) => <Skeleton key={item} className="h-28" />)}</div> : requests.isError ? <QueryError onRetry={() => requests.refetch()} /> : filtered.length ? <div className="grid gap-3 lg:grid-cols-2">{filtered.map((request) => <RequestCard key={request.id} request={request} />)}</div> : <EmptyRequests tab={tab} />}</div></Shell>;
}

function TabButton({ active, onClick, label, count, testId }: { active: boolean; onClick: () => void; label: string; count: number; testId: string }) { return <button onClick={onClick} className={`border-b-2 px-3 py-3 text-sm font-bold ${active ? 'border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'border-transparent muted'}`} data-testid={testId}>{label} <span className="ml-1 text-xs opacity-70">{count}</span></button>; }
function EmptyRequests({ tab }: { tab: string }) { return <div className="card flex flex-col items-center justify-center border-dashed px-5 py-14 text-center"><div className="mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]"><Construction size={25} /></div><h3 className="display text-xl font-bold">{tab === 'active' ? 'Henüz aktif talebin yok' : tab === 'past' ? 'Tamamlanan işlerin burada' : 'İptal edilen talep yok'}</h3><p className="muted mt-2 max-w-sm text-sm">İhtiyacın olduğunda Antalya’nın ustalarını buradan çağırabilirsin.</p>{tab === 'active' && <Link href="/talep" className="btn btn-primary mt-6" data-testid="link-empty-request"><Plus size={17} /> Talep oluştur</Link>}</div>; }
function RequestCard({ request }: { request: ServiceRequest }) { return <Link href={`/islerim/${request.id}`} className="card group block p-5 transition hover:-translate-y-0.5 hover:shadow-[var(--shadow-md)]" data-testid={`card-request-${request.id}`}><div className="flex items-start justify-between gap-4"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]"><Wrench size={16} /></span><div><p className="label mb-0">{request.categoryName}</p><h3 className="mt-1 font-bold">{request.title || 'Hizmet talebi'}</h3></div></div><ChevronRight className="muted mt-2" size={18} /></div><div className="mt-5 flex flex-wrap items-center gap-2 text-xs"><span className={`rounded-full px-2.5 py-1 font-bold ${request.status === 'İptal' ? 'bg-[#f5dcda] text-[#943f37]' : request.status === 'Tamamlandı' ? 'bg-[#dcebdc] text-[#3e7046]' : 'bg-[#fff0ba] text-[#896a12]'}`}>{statusLabels[request.status] ?? request.status}</span><span className="muted flex items-center gap-1"><MapPin size={13} /> {request.semt}, {request.mahalle}</span><span className="muted ml-auto">{formatDate(request.createdAt)}</span></div></Link>; }

function RequestDetail() {
  const params = useParams<{ id: string }>(); const id = Number(params.id); const detail = useGetRequestById(id); const locations = useGetLocations(); const update = useUpdateRequestStatus(); const client = useQueryClient(); const [, setLocation] = useLocation(); const request = detail.data; const location = (locations.data ?? []).find((item) => String(item.ustaId) === String(request?.assignedUstaId)); const canCancel = request?.canManage && isOpen(request.status);
  const cancel = () => { if (request && window.confirm('Bu talebi iptal etmek istediğinize emin misiniz?')) update.mutate({ id, data: { status: 'İptal' } }, { onSuccess: () => { client.invalidateQueries({ queryKey: getGetRequestsQueryKey() }); client.invalidateQueries({ queryKey: detail.queryKey }); } }); };
  if (detail.isLoading) return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><Skeleton className="h-72" /></Shell>; if (detail.isError || !request) return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><QueryError onRetry={() => detail.refetch()} /></Shell>;
  return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><div className="page-enter mx-auto max-w-4xl"><button onClick={() => setLocation('/islerim')} className="btn btn-quiet -ml-3 mb-4" data-testid="button-back-requests"><ArrowLeft size={17} /> İşlerime dön</button><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="space-y-5"><div className="card overflow-hidden"><div className="bg-[hsl(var(--secondary)/.55)] px-6 py-7"><div className="flex items-center justify-between"><span className="rounded-full bg-[hsl(var(--card)/.75)] px-3 py-1.5 text-xs font-bold">Talep #{request.id}</span><span className="muted text-xs">{formatDate(request.createdAt)}</span></div><h1 className="display mt-6 text-3xl font-bold tracking-[-.05em]">{request.title || request.categoryName}</h1><p className="muted mt-2 text-sm">{request.description || 'Açıklama eklenmemiş.'}</p></div><div className="p-6"><Progress status={request.status} /></div></div><div className="card p-6"><h2 className="display mb-4 text-lg font-bold">İş bilgileri</h2><InfoRow icon={<MapPin size={17} />} label="Adres" value={`${request.mahalle}, ${request.semt}${request.sokak ? `, ${request.sokak}` : ''}`} /><InfoRow icon={<CalendarDays size={17} />} label="Zamanlama" value={request.timeRange || 'Usta ile netleşecek'} /><InfoRow icon={<Zap size={17} />} label="Öncelik" value={request.priority} /></div></div><div className="space-y-5">{location ? <div className="card overflow-hidden"><div className="simple-map relative h-48"><div className="absolute left-1/2 top-1/2 flex h-12 w-12 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border-4 border-[hsl(var(--card))] bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-lg"><Navigation size={20} /></div></div><div className="flex items-center gap-3 p-4"><Avatar usta={{ id: location.ustaId, name: location.ustaName }} size="sm" /><div className="min-w-0 flex-1"><p className="font-bold">{location.ustaName}</p><p className="muted text-sm">{location.specialty}</p></div><Link href={`/usta/${location.ustaId}`} className="btn btn-quiet px-2" data-testid="link-assigned-usta"><ChevronRight size={19} /></Link></div></div> : <div className="card border-dashed p-6"><div className="mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--accent))]"><Clock3 size={19} /></div><h2 className="display text-lg font-bold">Usta aranıyor</h2><p className="muted mt-2 text-sm leading-6">Talebin ustalara iletildi. Eşleşme olduğunda burada göreceksin.</p></div>}{canCancel && <button disabled={update.isPending} onClick={cancel} className="btn w-full border border-[hsl(var(--destructive)/.3)] bg-transparent text-[hsl(var(--destructive))]" data-testid="button-cancel-request">{update.isPending ? <LoaderCircle className="animate-spin" size={17} /> : <X size={17} />} Talebi iptal et</button>}</div></div></div></Shell>;
}

function Progress({ status }: { status: string }) { const steps = ['Beklemede', 'Devam Ediyor', 'Tamamlandı']; const current = status === 'İptal' ? -1 : steps.indexOf(status); return <div className="relative flex justify-between">{steps.map((step, index) => <div key={step} className="relative z-[1] flex w-1/3 flex-col items-center gap-2 text-center"><span className={`flex h-9 w-9 items-center justify-center rounded-full border-2 ${index <= current ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'border-[hsl(var(--border))] bg-[hsl(var(--card))] muted'}`}>{index < current ? <Check size={17} /> : index + 1}</span><span className={`text-[11px] font-bold ${index <= current ? '' : 'muted'}`}>{index === 0 ? 'Talep alındı' : index === 1 ? 'Usta yolda' : 'İş tamamlandı'}</span></div>)}<div className="absolute left-[16%] right-[16%] top-4 h-0.5 bg-[hsl(var(--border))]"><div className="h-full bg-[hsl(var(--primary))] transition-all" style={{ width: `${current < 0 ? 0 : (current / 2) * 100}%` }} /></div></div>; }

function Notifications() {
  const requests = useGetRequests(); const [read, setRead] = useState<number[]>(() => JSON.parse(localStorage.getItem('usta-cepte-read-notifications') || '[]') as number[]); const notifications = (requests.data ?? []).map((request) => ({ id: request.id, title: statusLabels[request.status] ?? 'Talep güncellendi', text: `${request.title || request.categoryName} talebinin durumu güncellendi.`, date: request.createdAt })); const markRead = (id: number) => { const next = [...new Set([...read, id])]; setRead(next); localStorage.setItem('usta-cepte-read-notifications', JSON.stringify(next)); };
  return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><div className="page-enter mx-auto max-w-3xl"><PageHeading eyebrow="Bildirimler" title="Olan bitenden haberdar ol" /><div className="mb-6 flex items-center justify-between"><p className="muted text-sm">{notifications.filter((item) => !read.includes(item.id)).length ? `${notifications.filter((item) => !read.includes(item.id)).length} okunmamış bildirim` : 'Tüm bildirimler okundu'}</p>{notifications.length > 0 && <button onClick={() => { const next = notifications.map((item) => item.id); setRead(next); localStorage.setItem('usta-cepte-read-notifications', JSON.stringify(next)); }} className="btn btn-quiet text-xs" data-testid="button-mark-all-read">Tümünü okundu işaretle</button>}</div>{requests.isLoading ? <div className="space-y-3">{[1, 2, 3].map((item) => <Skeleton key={item} className="h-24" />)}</div> : requests.isError ? <QueryError onRetry={() => requests.refetch()} /> : notifications.length === 0 ? <div className="card p-12 text-center"><Bell className="mx-auto muted" /><h3 className="display mt-4 text-xl font-bold">Şimdilik sessiz</h3><p className="muted mt-2 text-sm">Talep oluşturduğunda gelişmeleri burada paylaşacağız.</p></div> : <div className="space-y-3">{notifications.map((item) => <Link href={`/islerim/${item.id}`} onClick={() => markRead(item.id)} className={`card flex gap-4 p-4 ${read.includes(item.id) ? 'opacity-70' : 'border-l-4 border-l-[hsl(var(--primary))]'}`} key={item.id} data-testid={`notification-${item.id}`}><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${read.includes(item.id) ? 'bg-[hsl(var(--muted))] muted' : 'bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]'}`}>{read.includes(item.id) ? <CircleCheck size={18} /> : <Bell size={18} />}</div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><p className="font-bold">{item.title}</p><span className="muted whitespace-nowrap text-xs">{formatDate(item.date)}</span></div><p className="muted mt-1 text-sm">{item.text}</p></div><ChevronRight className="muted mt-1" size={18} /></Link>)}</div>}</div></Shell>;
}

function Account() {
  const [userName, setUserName] = useState(() => localStorage.getItem('usta-cepte-user-name')); const [mode, setMode] = useState<'login' | 'register'>('login'); const [form, setForm] = useState({ name: '', phone: '', email: '', password: '', district: 'Muratpaşa', address: '' }); const register = useRegisterCustomer(); const update = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value })); const submit = (event: FormEvent) => { event.preventDefault(); if (mode === 'login') { const name = form.email.split('@')[0] || 'Antalya müşterisi'; localStorage.setItem('usta-cepte-user-name', name); setUserName(name); } else register.mutate({ data: { ...form, kvkkConsent: true, address: form.address || null } }, { onSuccess: (result) => { localStorage.setItem('usta-cepte-user-name', form.name); localStorage.setItem('usta-cepte-user-id', String(result.id)); setUserName(form.name); } }); }; const logout = () => { localStorage.removeItem('usta-cepte-user-name'); localStorage.removeItem('usta-cepte-user-id'); setUserName(null); };
  if (userName) return <Shell userName={userName}><div className="page-enter mx-auto max-w-3xl"><PageHeading eyebrow="Hesabım" title={`Merhaba, ${userName}`} /><div className="card mb-5 flex items-center gap-4 bg-[hsl(var(--secondary)/.35)] p-5"><Avatar usta={{ name: userName }} size="lg" /><div className="flex-1"><p className="label">Müşteri hesabı</p><h2 className="display text-xl font-bold">{userName}</h2><p className="muted text-sm">Antalya · Usta Cepte müşterisi</p></div><ShieldCheck className="text-[hsl(var(--primary))]" /></div><div className="card divide-y divide-[hsl(var(--border))]"><AccountRow icon={<Settings2 size={18} />} title="Hesap ayarları" detail="İletişim ve adres bilgilerini düzenle" /><AccountRow icon={<LockKeyhole size={18} />} title="Gizlilik ve güvenlik" detail="Bilgilerin güvende" /><AccountRow icon={<MessageCircle size={18} />} title="Destek" detail="Bir sorunuz mu var?" /><button onClick={logout} className="flex w-full items-center gap-3 p-5 text-left text-[hsl(var(--destructive))] hover:bg-[hsl(var(--muted))]" data-testid="button-logout"><ArrowLeft size={18} /><span><strong className="block">Çıkış yap</strong><small className="muted">Bu cihazdaki hesabı kapat</small></span></button></div></div></Shell>;
  return <Shell userName={null}><div className="page-enter mx-auto grid max-w-4xl gap-8 lg:grid-cols-[.9fr_1.1fr] lg:items-center"><div><p className="label text-[hsl(var(--primary))]">Hesabım</p><h1 className="display mt-4 text-4xl font-bold leading-[1.05] tracking-[-.06em] md:text-5xl">İşlerin,<br /><span className="text-[hsl(var(--primary))]">tek yerde.</span></h1><p className="muted mt-5 max-w-sm leading-7">Talep geçmişini ve iş durumunu her yerden takip etmek için hesabına giriş yap.</p></div><div className="card p-6 md:p-8"><div className="mb-6 flex rounded-xl bg-[hsl(var(--muted))] p-1"><button onClick={() => setMode('login')} className={`flex-1 rounded-lg py-2.5 text-sm font-bold ${mode === 'login' ? 'bg-[hsl(var(--card))] shadow-sm' : 'muted'}`} data-testid="tab-login">Giriş yap</button><button onClick={() => setMode('register')} className={`flex-1 rounded-lg py-2.5 text-sm font-bold ${mode === 'register' ? 'bg-[hsl(var(--card))] shadow-sm' : 'muted'}`} data-testid="tab-register">Kayıt ol</button></div><form onSubmit={submit} className="space-y-4">{mode === 'register' && <Field label="Ad soyad" value={form.name} onChange={(value) => update('name', value)} placeholder="Adınız ve soyadınız" testId="input-register-name" required />}<Field label="E-posta" type="email" value={form.email} onChange={(value) => update('email', value)} placeholder="ornek@mail.com" testId="input-email" required /><Field label="Telefon" value={form.phone} onChange={(value) => update('phone', value)} placeholder="05xx xxx xx xx" testId="input-phone" required={mode === 'register'} /><Field label="Şifre" type="password" value={form.password} onChange={(value) => update('password', value)} placeholder="Şifreniz" testId="input-password" required /><button disabled={register.isPending} className="btn btn-primary mt-2 w-full" data-testid="button-account-submit">{register.isPending ? <LoaderCircle className="animate-spin" size={17} /> : mode === 'login' ? <ArrowRight size={17} /> : <UserRoundPlus size={17} />}{mode === 'login' ? 'Giriş yap' : 'Hesap oluştur'}</button>{register.isError && <p className="text-sm font-semibold text-[hsl(var(--destructive))]">Kayıt sırasında bir sorun oldu. Bilgileri kontrol edip tekrar deneyin.</p>}<p className="muted flex items-center justify-center gap-1.5 pt-2 text-center text-xs"><LockKeyhole size={13} /> Bilgilerin yalnızca hesabını yönetmek için kullanılır.</p></form></div></div></Shell>;
}
function Field({ label, value, onChange, placeholder, type = 'text', testId, required = false }: { label: string; value: string; onChange: (value: string) => void; placeholder: string; type?: string; testId: string; required?: boolean }) { return <label><span className="label">{label}</span><input className="field" type={type} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} required={required} data-testid={testId} /></label>; }
function AccountRow({ icon, title, detail }: { icon: ReactNode; title: string; detail: string }) { return <button className="flex w-full items-center gap-3 p-5 text-left hover:bg-[hsl(var(--muted))]" onClick={() => window.alert('Bu ayar yakında hesabınıza eklenecek.')} data-testid={`button-account-${title.replaceAll(' ', '-').toLowerCase()}`}><span className="text-[hsl(var(--primary))]">{icon}</span><span className="flex-1"><strong className="block">{title}</strong><small className="muted">{detail}</small></span><ChevronRight className="muted" size={18} /></button>; }

function NewRequest() {
  const params = useMemo(() => new URLSearchParams(window.location.search), []); const initial = params.get('category') || ''; const [step, setStep] = useState(1); const [form, setForm] = useState({ categoryId: initial, categoryName: categoryName(initial), title: '', description: '', semt: 'Muratpaşa', mahalle: '', sokak: '', priority: 'Normal', timeRange: 'Müsait olduğumda' }); const [photoName, setPhotoName] = useState(''); const create = useCreateRequest(); const [, setLocation] = useLocation(); const update = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value, ...(key === 'categoryId' ? { categoryName: categoryName(value) } : {}) })); const submit = (event: FormEvent) => { event.preventDefault(); create.mutate({ data: { ...form, title: form.title || null, description: form.description || null, sokak: form.sokak || null, timeRange: form.timeRange || null } as ServiceRequestInput }, { onSuccess: (request) => setLocation(`/islerim/${request.id}`) }); };
  return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><div className="page-enter mx-auto max-w-5xl"><button onClick={() => step > 1 ? setStep(step - 1) : setLocation('/')} className="btn btn-quiet -ml-3 mb-4" data-testid="button-back-request-flow"><ArrowLeft size={17} /> Geri</button><div className="mb-8 flex items-end justify-between"><div><p className="label mb-1 text-[hsl(var(--primary))]">Talep oluştur</p><h1 className="display text-3xl font-bold tracking-[-.05em] md:text-4xl">{step === 1 ? 'Hangi iş için usta lazım?' : step === 2 ? 'Nereye gelelim?' : 'Ne zaman gelsin?'}</h1></div><span className="muted text-sm font-bold">0{step} / 03</span></div><div className="mb-8 flex gap-2">{[1, 2, 3].map((item) => <div key={item} className={`h-1.5 flex-1 rounded-full ${item <= step ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))]'}`} />)}</div><div className="grid gap-6 lg:grid-cols-[1fr_18rem]"><form onSubmit={submit} className="card p-5 md:p-8">{step === 1 && <div><p className="muted mb-6">Birini seç, gerisini birlikte tamamlarız.</p><div className="space-y-2">{categories.map(({ id, name, icon: Icon }) => <button type="button" key={id} onClick={() => update('categoryId', id)} className={`flex w-full items-center gap-3 rounded-xl border p-4 text-left transition ${form.categoryId === id ? 'border-[hsl(var(--primary))] bg-[hsl(var(--accent)/.28)]' : 'border-[hsl(var(--border))] hover:border-[hsl(var(--primary)/.5)]'}`} data-testid={`select-category-${id}`}><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]"><Icon size={18} /></span><span className="font-bold">{name}</span>{form.categoryId === id && <Check className="ml-auto text-[hsl(var(--primary))]" size={18} />}</button>)}</div><label className="mt-6 block"><span className="label">İstersen kısa bir not ekle</span><input className="field" value={form.title} onChange={(e) => update('title', e.target.value)} placeholder="Örn. Salondaki priz çalışmıyor" data-testid="input-request-title" /></label><button type="button" disabled={!form.categoryId} onClick={() => setStep(2)} className="btn btn-primary mt-6 w-full" data-testid="button-request-next-1">Devam et <ArrowRight size={17} /></button></div>}{step === 2 && <div><p className="muted mb-6">Ustanın gelebileceği adresi yazalım.</p><div className="grid gap-4"><label><span className="label">İlçe</span><select className="field" value={form.semt} onChange={(e) => update('semt', e.target.value)} data-testid="select-district"><option>Muratpaşa</option><option>Konyaaltı</option><option>Kepez</option><option>Alanya</option><option>Manavgat</option><option>Serik</option></select></label><Field label="Mahalle" value={form.mahalle} onChange={(value) => update('mahalle', value)} placeholder="Mahalle adı" testId="input-neighborhood" required /><Field label="Sokak / bina (opsiyonel)" value={form.sokak} onChange={(value) => update('sokak', value)} placeholder="Sokak, bina no" testId="input-street" /></div><div className="mt-5 flex items-start gap-3 rounded-xl bg-[hsl(var(--secondary)/.35)] p-4 text-sm"><MapPin size={18} className="mt-0.5 shrink-0 text-[hsl(var(--secondary-foreground))]" /><span className="text-[hsl(var(--secondary-foreground))]">Adresini yalnızca eşleşen usta ile paylaşırız.</span></div><button type="button" disabled={!form.mahalle} onClick={() => setStep(3)} className="btn btn-primary mt-6 w-full" data-testid="button-request-next-2">Devam et <ArrowRight size={17} /></button></div>}{step === 3 && <div><p className="muted mb-6">Ustanın sana uygun gelmesini sağlayalım.</p><div><span className="label">Öncelik</span><div className="grid grid-cols-3 gap-2">{['Normal', 'Acil', 'Çok acil'].map((priority) => <button type="button" key={priority} onClick={() => update('priority', priority)} className={`rounded-xl border px-3 py-3 text-sm font-bold ${form.priority === priority ? 'border-[hsl(var(--primary))] bg-[hsl(var(--accent)/.28)] text-[hsl(var(--primary))]' : 'border-[hsl(var(--border))]'}`} data-testid={`select-priority-${priority}`}>{priority}</button>)}</div></div><div className="mt-6"><span className="label">Zaman aralığı</span><div className="grid gap-2 sm:grid-cols-3">{['Müsait olduğumda', 'Bugün', 'Yarın'].map((range) => <button type="button" key={range} onClick={() => update('timeRange', range)} className={`flex items-center justify-center gap-2 rounded-xl border px-3 py-3 text-sm font-bold ${form.timeRange === range ? 'border-[hsl(var(--primary))] bg-[hsl(var(--accent)/.28)] text-[hsl(var(--primary))]' : 'border-[hsl(var(--border))]'}`} data-testid={`select-time-${range}`}><Clock3 size={16} />{range}</button>)}</div></div><label className="mt-6 flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[hsl(var(--border))] p-4 hover:border-[hsl(var(--primary))]"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--muted))]"><ImagePlus size={19} /></span><span className="flex-1"><strong className="block text-sm">Fotoğraf ekle</strong><small className="muted">{photoName || 'İstersen işini gösteren bir fotoğraf seç'}</small></span><input type="file" accept="image/*" className="hidden" onChange={(e) => setPhotoName(e.target.files?.[0]?.name ?? '')} data-testid="input-request-photo" /></label><div className="mt-5 flex items-start gap-3 rounded-xl bg-[hsl(var(--accent)/.28)] p-4 text-sm"><Info size={18} className="mt-0.5 shrink-0" /><span>Fotoğraflar bu ilk sürümde yalnızca cihazında seçilir; talep kaydına gönderilmez.</span></div><button disabled={create.isPending} className="btn btn-primary mt-6 w-full" data-testid="button-submit-request">{create.isPending ? <LoaderCircle className="animate-spin" size={17} /> : <ArrowRight size={17} />} Talebi gönder</button>{create.isError && <p className="mt-3 text-center text-sm font-semibold text-[hsl(var(--destructive))]">Talep gönderilemedi. Tekrar deneyin.</p>}</div>}</form><RequestSummary form={form} step={step} /></div></div></Shell>;
}

function RequestSummary({ form, step }: { form: { categoryName: string; title: string; semt: string; mahalle: string; priority: string; timeRange: string }; step: number }) {
  return <aside className="concierge-summary hidden lg:block"><div className="card editorial-card overflow-hidden"><div className="bg-[hsl(var(--secondary)/.35)] p-5"><p className="label mb-2">Talep özeti</p><h2 className="display text-2xl font-bold">Size uygun<br />bir usta bulalım.</h2></div><div className="space-y-4 p-5"><SummaryRow label="Hizmet" value={form.categoryName || 'Henüz seçilmedi'} active={step === 1} /><SummaryRow label="Adres" value={form.mahalle ? `${form.mahalle}, ${form.semt}` : 'Henüz eklenmedi'} active={step === 2} /><SummaryRow label="Zaman" value={step === 3 ? `${form.priority} · ${form.timeRange}` : 'Henüz seçilmedi'} active={step === 3} /></div><div className="border-t border-[hsl(var(--border))] p-5"><p className="muted text-xs leading-5">Talebinizi aldıktan sonra size en uygun ustalarla iletişime geçeceğiz.</p></div></div></aside>;
}

function SummaryRow({ label, value, active }: { label: string; value: string; active: boolean }) {
  return <div className={`border-l-2 pl-3 ${active ? 'border-[hsl(var(--primary))]' : 'border-[hsl(var(--border))]'}`}><p className="label mb-1">{label}</p><p className={`text-sm font-semibold ${value.startsWith('Henüz') ? 'muted' : ''}`}>{value}</p></div>;
}

function UstaProfile() {
  const params = useParams<{ id: string }>(); const id = Number(params.id); const usta = useGetUstaById(id); const [, setLocation] = useLocation();
  if (usta.isLoading) return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><Skeleton className="mx-auto h-72 max-w-3xl" /></Shell>; if (usta.isError || !usta.data) return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><QueryError onRetry={() => usta.refetch()} /></Shell>; const person = usta.data;
  return <Shell userName={localStorage.getItem('usta-cepte-user-name')}><div className="page-enter mx-auto max-w-3xl"><button onClick={() => setLocation('/')} className="btn btn-quiet -ml-3 mb-4" data-testid="button-back-home"><ArrowLeft size={17} /> Ana sayfaya dön</button><div className="card overflow-hidden"><div className="bg-[hsl(var(--secondary)/.55)] px-6 py-9 md:px-9"><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><Avatar usta={person} size="lg" /><div><div className="flex items-center gap-2"><h1 className="display text-3xl font-bold tracking-[-.05em]">{person.name}</h1>{person.verified && <ShieldCheck size={20} className="text-[hsl(var(--primary))]" />}</div><p className="muted mt-1">{person.specialty}</p><div className="mt-4 flex flex-wrap gap-2 text-xs font-bold"><span className="flex items-center gap-1 rounded-full bg-[hsl(var(--card)/.7)] px-3 py-1.5"><Star size={13} fill="currentColor" className="text-[#c48a19]" /> {person.rating.toFixed(1)} ({person.reviewCount ?? 0} yorum)</span><span className={`rounded-full px-3 py-1.5 ${person.isOnline ? 'bg-[#dcebdc] text-[#3e7046]' : 'bg-[hsl(var(--muted))] muted'}`}>{person.isOnline ? 'Şimdi müsait' : 'Şu an çevrimdışı'}</span></div></div></div></div><div className="space-y-7 p-6 md:p-9"><div><p className="label">Usta hakkında</p><p className="mt-2 leading-7">{person.bio || 'İşini özenle yapan, Antalya ve çevresinde hizmet veren deneyimli bir usta.'}</p></div><div className="grid grid-cols-2 gap-3"><div className="rounded-xl bg-[hsl(var(--muted))] p-4"><p className="label mb-1">Hizmet bölgesi</p><p className="font-bold">{person.district || 'Antalya'}</p></div><div className="rounded-xl bg-[hsl(var(--muted))] p-4"><p className="label mb-1">Değerlendirme</p><p className="flex items-center gap-1 font-bold"><Star size={15} fill="currentColor" className="text-[#c48a19]" /> {person.rating.toFixed(1)} / 5</p></div></div><div className="flex flex-col gap-3 sm:flex-row"><Link href={`/talep?category=${person.categoryId || ''}`} className="btn btn-primary flex-1" data-testid="link-request-usta"><Plus size={17} /> Bu ustadan talep et</Link><button onClick={() => window.alert('Usta iletişim bilgileri eşleşme sonrası paylaşılır.')} className="btn btn-secondary flex-1" data-testid="button-contact-usta"><Phone size={17} /> İletişim bilgisi</button></div></div></div></div></Shell>;
}

function PageHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="label mb-1 text-[hsl(var(--primary))]">{eyebrow}</p><h1 className="display text-3xl font-bold tracking-[-.06em] md:text-4xl">{title}</h1></div>{action}</div>; }
function InfoRow({ icon, label, value }: { icon: ReactNode; label: string; value: string }) { return <div className="flex gap-3 border-b border-[hsl(var(--border))] py-3 last:border-0"><span className="mt-0.5 text-[hsl(var(--primary))]">{icon}</span><div><p className="label mb-0">{label}</p><p className="mt-0.5 text-sm font-semibold">{value}</p></div></div>; }
function Router() { const [location] = useLocation(); useEffect(() => { document.title = location === '/' ? 'Usta Cepte — Antalya’da yanında' : `Usta Cepte · ${location.slice(1).split('/')[0] || 'Antalya'}`; }, [location]); return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Home} /><Route path="/islerim" component={RequestList} /><Route path="/islerim/:id" component={RequestDetail} /><Route path="/bildirimler" component={Notifications} /><Route path="/hesabim" component={Account} /><Route path="/talep" component={NewRequest} /><Route path="/usta/:id" component={UstaProfile} /><Route component={NotFound} /></Switch></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;